/* Entrance configuration: set enabled:false to disable; duration controls desktop timing. */
const INTRO={enabled:true,duration:5000,mobileDuration:3000};
(()=>{'use strict';
const legacy={'#book':'/contact/','#why-us':'/about/','#process':'/about/','#testimonials':'/reviews/','#service-area':'/service-areas/'};if(location.pathname==='/'&&legacy[location.hash]){location.replace(legacy[location.hash]);return;}
const menu=document.querySelector('.menu-button'),mobile=document.querySelector('#mobile-nav');
function closeMenu(){mobile.hidden=true;menu.setAttribute('aria-expanded','false');document.querySelector('.sticky-call')?.classList.toggle('visible',scrollY>650)}
menu?.addEventListener('click',()=>{const open=mobile.hidden;mobile.hidden=!open;menu.setAttribute('aria-expanded',String(open));if(open)document.querySelector('.sticky-call')?.classList.remove('visible')});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeMenu();document.querySelectorAll('.nav-drop').forEach(d=>d.open=false)}});
document.addEventListener('click',event=>{document.querySelectorAll('.nav-drop[open]').forEach(d=>{if(!d.contains(event.target))d.open=false})});
document.querySelectorAll('.nav-drop').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.nav-drop').forEach(x=>{if(x!==d)x.open=false})}));
const sticky=document.querySelector('.sticky-call'),hero=document.querySelector('.hero')||document.querySelector('.page-hero')||document.querySelector('.service-hero');
if(hero&&sticky)new IntersectionObserver(([entry])=>sticky.classList.toggle('visible',!entry.isIntersecting&&mobile.hidden),{threshold:0}).observe(hero);
const form=document.querySelector('#request-planner');if(form){form.addEventListener('submit',ev=>{ev.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);const summary=`Service request preparation — not submitted\nName: ${f.get('name')}\nPhone: ${f.get('phone')}\nCommunity: ${f.get('area')}\nService: ${f.get('service')}\nIssue: ${f.get('issue')}`;document.querySelector('#request-summary').value=summary;document.querySelector('#request-result').hidden=false;document.querySelector('#request-result').scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})});document.querySelector('#copy-summary').addEventListener('click',async ev=>{try{await navigator.clipboard.writeText(document.querySelector('#request-summary').value);ev.target.textContent='Copied — continue to the booking form'}catch{document.querySelector('#request-summary').select();ev.target.textContent='Select and copy the summary above'}})}
// Keep the original Google Maps JavaScript integration, center, zoom and radius.
const coverage=document.querySelector('.coverage');if(coverage){let areaData=[],map=null,marker=null,pending=coverage.dataset.selected||'',loading=false,fallbackMode=false,request=0;const host=document.querySelector('#service-map'),status=document.querySelector('#map-status');
const dataReady=fetch('/areas.json').then(r=>{if(!r.ok)throw Error('Area directory unavailable');return r.json()}).then(d=>areaData=d).catch(()=>{status.textContent='The location directory could not load. Use the area links or call to confirm coverage.';return []});
function fallback(){loading=false;fallbackMode=true;host.innerHTML='';const area=areaData.find(a=>a.slug===pending);const iframe=document.createElement('iframe');iframe.title='Google Maps: '+(area?.name||'Greater Tampa Bay');iframe.src='https://maps.google.com/maps?q='+encodeURIComponent((area?.name||'Tampa Bay')+', Florida')+'&z='+(area?12:9)+'&output=embed';iframe.loading='lazy';iframe.referrerPolicy='no-referrer-when-downgrade';iframe.allowFullscreen=true;iframe.style.cssText='border:0;width:100%;height:100%';host.append(iframe);status.textContent='The original API map was unavailable. Showing a Google Maps query embed instead. Selected location is a community, not an office.'}function focusArea(){if(!pending||!map||!window.google)return;const a=areaData.find(a=>a.slug===pending);if(!a)return;const id=++request;const geocoder=new google.maps.Geocoder();geocoder.geocode({address:a.name+', '+a.county+' County, Florida, USA'},(results,st)=>{if(id!==request)return;if(st==='OK'&&results[0]){const p=results[0].geometry.location;map.panTo(p);map.setZoom(12);if(marker)marker.setMap(null);marker=new google.maps.Marker({map,position:p,title:a.name+' service area'});status.textContent='Showing '+a.name+'. Marker indicates the community, not a Plumbing ICU office. Call to confirm your address.'}else{status.textContent='Google could not focus this location. Use the location page or open Google Maps.'}})}
window.gm_authFailure=fallback;
window.onICUMapReady=async()=>{await dataReady;try{if(!window.google?.maps)throw Error();host.innerHTML='';map=new google.maps.Map(host,{center:{lat:27.9477,lng:-82.4584},zoom:9,mapTypeId:'roadmap',mapTypeControl:false,streetViewControl:false,fullscreenControl:true,gestureHandling:'cooperative',styles:[{elementType:'geometry',stylers:[{color:'#eef2f7'}]},{elementType:'labels.text.fill',stylers:[{color:'#374151'}]},{elementType:'labels.text.stroke',stylers:[{color:'#f8fafc'}]},{featureType:'water',elementType:'geometry',stylers:[{color:'#b8d4ea'}]},{featureType:'road.highway',elementType:'geometry',stylers:[{color:'#dde5ef'}]},{featureType:'road',elementType:'geometry',stylers:[{color:'#ffffff'}]},{featureType:'poi',stylers:[{visibility:'off'}]},{featureType:'transit',stylers:[{visibility:'off'}]}]});new google.maps.Circle({map,center:{lat:27.9477,lng:-82.4584},radius:72420,strokeColor:'#1E6BFF',strokeOpacity:.75,strokeWeight:2,fillColor:'#1E6BFF',fillOpacity:.09});focusArea()}catch{fallback()}};
function loadMap(){if(fallbackMode){fallback();return}if(map){focusArea();return}if(loading)return;loading=true;host.innerHTML='<p>Loading Google Maps…</p>';const script=document.createElement('script');script.src='https://maps.googleapis.com/maps/api/js?key=AIzaSyBY7dTeOyHVcE3RZXTpvPVRFc_fzX_Mha4&callback=onICUMapReady';script.async=true;script.onerror=fallback;document.head.append(script);setTimeout(()=>{if(!map)fallback()},12000)}
document.querySelector('.load-map')?.addEventListener('click',loadMap);
document.querySelector('#area-search').addEventListener('input',ev=>{let count=0;document.querySelectorAll('[data-area]').forEach(btn=>{const show=btn.textContent.toLowerCase().includes(ev.target.value.toLowerCase());btn.hidden=!show;if(show)count++});document.querySelector('.search-empty').hidden=count!==0});
document.querySelectorAll('[data-area]').forEach(btn=>btn.addEventListener('click',async()=>{await dataReady;pending=btn.dataset.area;document.querySelectorAll('[data-area]').forEach(x=>x.setAttribute('aria-pressed',String(x===btn)));const a=areaData.find(x=>x.slug===pending);document.querySelector('#location-name').textContent=a?.name||btn.textContent.replace('↗','');const link=document.querySelector('#location-link');link.href='/service-areas/'+pending+'/';link.textContent='Explore this area ↗';loadMap()}));}

})();
